import design_final as D, check as C, math
from geom import centroid, point_in_poly, seg_poly_param_intervals
d = D.build(); B = d['buildings']
def sampled_block(src, zs, rcv, zr, blockers, n):
    for k in range(1, n):
        t = k / n
        p = (src[0] + (rcv[0]-src[0])*t, src[1] + (rcv[1]-src[1])*t)
        z = zs + (zr - zs)*t
        for bid,(poly,h) in blockers.items():
            if point_in_poly(p, poly) and h > z: return bid
    return None
for ph in (1,2):
    Bp = {k:v for k,v in B.items() if v['phase']<=ph}
    for src_id in ('GEN','CTP'):
        s = Bp[src_id]; c = centroid(s['poly']); hs = max(s['h'],2)
        blk = {k:(o['poly'],o['h']) for k,o in Bp.items() if k!=src_id and o['type'] not in ('stormwater_retention','generator_yard','cooling_plant')}
        for rid, rp in C.RECEPTORS.items():
            res = {n: sampled_block(c, hs, rp, 1.5, blk, n) for n in (10, 20, 30, 50, 100)}
            ivs = {k: [round((t1-t0)*math.dist(c,rp),1) for t0,t1 in seg_poly_param_intervals(c, rp, v[0])] for k,v in blk.items()}
            ivs = {k:v for k,v in ivs.items() if v}
            print(f'ph{ph} {src_id}->{rid}: sampled blockers by N={res}  crossing lengths={ivs}')
# visibility targets with coarse sampling
g = B['GEN']; c = centroid(g['poly'])
blk = {k:(o['poly'],o['h']) for k,o in B.items() if k not in ('GEN','DH_P2') and o['type'] not in ('stormwater_retention','cooling_plant')}
for rid, rp in C.RECEPTORS.items():
    worst = []
    for tp in [c]+g['poly']:
        for n in (20, 30, 50):
            worst.append(sampled_block(rp, 1.7, tp, 3.5, blk, n) is not None)
    print('visibility', rid, 'all blocked (N=20/30/50):', all(worst))
